HOST="import hashlib,json,pathlib,subprocess,sys,urllib.request\nj=json.load(sys.stdin);base=pathlib.Path('/data/wio/sglang-mech36-20261018');assert json.loads((base/'owner.json').read_text())['task']=='sglang-pd-spec-36'\nx=json.loads(subprocess.run(['docker','inspect','--format','{{json .}}',j['container']],capture_output=True,text=True,check=True,timeout=25).stdout);assert x['Id']==j['container_id'] and x['Config']['Labels']['task']=='sglang-pd-spec-36' and x['Config']['Labels']['run']==j['run'] and x['State']['Running']\nopener=urllib.request.build_opener(urllib.request.ProxyHandler({}))\nwith opener.open('http://172.16.12.'+str(j['node'])+':'+str(39044 if j['node']==44 else 39046)+'/ready',timeout=5) as response:assert response.status==200\nv={'node':j['node'],'container_id':x['Id'],'state':x['State'],'pure_ready':200,'read_only':True,'inference_requests':0}\nif j['node']==44:\n model=pathlib.Path(j['model_path']);assert model.resolve().is_relative_to(base.resolve());v['model_metadata']={}\n for name in ['config.json','generation_config.json','tokenizer_config.json']:\n  f=model/name\n  if f.is_file():data=f.read_bytes();assert len(data)<1024**2;v['model_metadata'][name]={'sha256':hashlib.sha256(data).hexdigest(),'json':json.loads(data)}\nprint(json.dumps(v))\n"
IMAGE="import hashlib,json,pathlib,subprocess,sys\nroot=pathlib.Path('/sgl-workspace/sglang');v={'sources':{},'Torch_imported':'torch' in sys.modules,'NPU_device_nodes_absent':not any(pathlib.Path('/dev').glob('davinci*'))}\nfiles=['sgl-model-gateway/src/routers/http/pd_router.rs','python/sglang/srt/managers/io_struct.py','python/sglang/srt/sampling/sampling_params.py','python/sglang/srt/disaggregation/prefill.py','python/sglang/srt/disaggregation/decode.py','python/sglang/srt/disaggregation/common/conn.py','python/sglang/srt/disaggregation/utils.py','python/sglang/srt/managers/tokenizer_manager.py','python/sglang/srt/entrypoints/http_server.py']\nfor name in files:\n p=root/name\n if not p.is_file():v['sources'][name]={'exists':False};continue\n data=p.read_bytes();assert len(data)<1500000\n q=subprocess.run(['git','-c','safe.directory='+str(root),'show','HEAD:'+name],cwd=root,capture_output=True,timeout=15);assert q.returncode==0 and q.stdout==data,name\n v['sources'][name]={'exists':True,'sha256':hashlib.sha256(data).hexdigest(),'bytes':len(data),'matches_HEAD':True,'source':data.decode()}\nv['wire_examples']=[]\nfor p in sorted((root/'test').rglob('*.py')):\n data=p.read_bytes()\n if len(data)>150000:continue\n text=data.decode(errors='replace')\n if 'bootstrap_room' not in text or 'generate' not in text:continue\n lines=text.splitlines();v['wire_examples'].append({'path':str(p),'sha256':hashlib.sha256(data).hexdigest(),'contexts':[{'line':i+1,'text':'\\n'.join(lines[max(0,i-12):min(len(lines),i+20)])} for i,line in enumerate(lines) if 'bootstrap_room' in line]})\n if len(v['wire_examples'])>=12:break\nassert not v['Torch_imported'] and v['NPU_device_nodes_absent'];print(json.dumps(v))\n"
